:root {
  color-scheme: light dark;

  --ocean-surface: light-dark(#F5F6F8, #121419);
  --ocean-raised: light-dark(#FFFFFF, #1A1D24);
  --ocean-ink: light-dark(#15181F, #ECEEF2);
  --ocean-ink-muted: light-dark(#5B6270, #969CAA);
  --ocean-ink-faint: light-dark(#A3A9B5, #5E6473);
  --ocean-line: light-dark(#DDE1E7, #2A2E37);
  --ocean-control: light-dark(#E7EAEF, #2B303A);
  --ocean-download: light-dark(#2F6FE4, #5B8DEF);
  --ocean-upload: light-dark(#C8731A, #C97C26);

  --ocean-radius-control: 12px;
  --ocean-radius-panel: 16px;
  --ocean-radius-panel-lg: 20px;

  --ocean-shadow-popup: 0 12px 32px -8px light-dark(rgba(26, 36, 34, 0.18), rgba(0, 0, 0, 0.6));
}

:root.light {
  color-scheme: light;
}

:root.dark {
  color-scheme: dark;
}

@theme inline {
  --color-surface: var(--ocean-surface);
  --color-raised: var(--ocean-raised);
  --color-ink: var(--ocean-ink);
  --color-ink-muted: var(--ocean-ink-muted);
  --color-ink-faint: var(--ocean-ink-faint);
  --color-line: var(--ocean-line);
  --color-control: var(--ocean-control);
  --color-accent: var(--ocean-download);
  --color-accent-alt: var(--ocean-upload);

  --radius-control: var(--ocean-radius-control);
  --radius-panel: var(--ocean-radius-panel);
  --radius-panel-lg: var(--ocean-radius-panel-lg);

  --font-sans: var(--font-barlow, "Barlow"), system-ui, sans-serif;
  --font-condensed:
    var(--font-barlow-semi-condensed, "Barlow Semi Condensed"), var(--font-barlow, "Barlow"),
    system-ui, sans-serif;

  --shadow-popup: var(--ocean-shadow-popup);
}
